// Push gate: promo limits (3 per local day, 2h apart); security is never limited.

const MAX_PROMOS_PER_DAY = 3;
const MIN_GAP_MS = 2 * 60 * 60 * 1000;

const formatters = new Map();

function dayKey(ms, timeZone) {
  let f = formatters.get(timeZone);
  if (!f) {
    f = new Intl.DateTimeFormat('en-CA', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
    });
    formatters.set(timeZone, f);
  }
  return f.format(ms);
}

export function createGate() {
  const promosByUser = new Map(); // userId -> Map(id -> timestamp ms)
  const sends = new Map(); // id -> { userId, promo }
  let counter = 0;

  const deny = (rule) => ({ allowed: false, rule, id: null });

  function request({ userId, timeZone, category, now }) {
    const ms = now instanceof Date ? now.getTime() : NaN;
    if (!Number.isFinite(ms)) return deny('invalid-time');
    if (category !== 'promo' && category !== 'security') return deny('unknown-category');

    if (category === 'promo') {
      let today;
      try {
        today = dayKey(ms, timeZone);
      } catch {
        return deny('invalid-time-zone');
      }
      const mine = promosByUser.get(userId);
      if (mine) {
        let count = 0;
        let tooClose = false;
        for (const t of mine.values()) {
          if (dayKey(t, timeZone) === today) count++;
          if (Math.abs(ms - t) < MIN_GAP_MS) tooClose = true;
        }
        if (count >= MAX_PROMOS_PER_DAY) return deny('daily-cap');
        if (tooClose) return deny('min-gap');
      }
    }

    const id = `push-${++counter}`;
    if (category === 'promo') {
      let mine = promosByUser.get(userId);
      if (!mine) promosByUser.set(userId, (mine = new Map()));
      mine.set(id, ms);
    }
    sends.set(id, { userId, promo: category === 'promo' });
    return { allowed: true, rule: '', id };
  }

  function cancel(id) {
    const s = sends.get(id);
    if (!s) return;
    sends.delete(id);
    if (s.promo) {
      const mine = promosByUser.get(s.userId);
      mine.delete(id);
      if (mine.size === 0) promosByUser.delete(s.userId);
    }
  }

  return { request, cancel };
}

import assert from 'node:assert/strict';
import { createGate } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round8-final/d-sonnet/work/knock-d2-2/bot.mjs';

const LA = 'America/Los_Angeles';
const d = (s) => new Date(s);
const p = (g, u, tz, s) => g.request({ userId: u, timeZone: tz, category: 'promo', now: d(s) });

// cap + gap, local midnight (LA = UTC-7 in Oct => midnight is 07:00Z)
let g = createGate();
assert.ok(p(g, 'a', LA, '2026-10-20T07:00:00Z').allowed); // 00:00 local
assert.equal(p(g, 'a', LA, '2026-10-20T08:59:59Z').rule, 'min-gap');
assert.ok(p(g, 'a', LA, '2026-10-20T09:00:00Z').allowed); // exactly 2h
assert.ok(p(g, 'a', LA, '2026-10-20T11:00:00Z').allowed);
assert.equal(p(g, 'a', LA, '2026-10-20T13:00:00Z').rule, 'daily-cap');
assert.equal(p(g, 'a', LA, '2026-10-21T06:59:00Z').rule, 'daily-cap'); // 23:59 local still same day
assert.ok(p(g, 'a', LA, '2026-10-21T07:00:00Z').allowed); // next local day
// other user / other tz unaffected; UTC day differs from local day
assert.ok(p(g, 'b', LA, '2026-10-20T13:00:00Z').allowed);
// security unlimited, doesn't consume promo budget
g = createGate();
for (let i = 0; i < 10; i++) assert.ok(g.request({ userId: 'a', timeZone: LA, category: 'security', now: d('2026-10-20T10:00:00Z') }).allowed);
assert.ok(p(g, 'a', LA, '2026-10-20T10:00:00Z').allowed);
// cancel frees slot
g = createGate();
const r1 = p(g, 'a', 'Europe/Berlin', '2026-10-20T10:00:00Z');
assert.equal(p(g, 'a', 'Europe/Berlin', '2026-10-20T10:30:00Z').rule, 'min-gap');
g.cancel(r1.id); g.cancel(r1.id); g.cancel('nope');
assert.ok(p(g, 'a', 'Europe/Berlin', '2026-10-20T10:30:00Z').allowed);
// DST end day in Berlin (25h day, 2026-10-25)
g = createGate();
for (const t of ['2026-10-24T22:00:00Z', '2026-10-25T00:00:00Z', '2026-10-25T02:00:00Z'])
  assert.ok(p(g, 'a', 'Europe/Berlin', t).allowed);
assert.equal(p(g, 'a', 'Europe/Berlin', '2026-10-25T04:00:00Z').rule, 'daily-cap');
assert.ok(p(g, 'a', 'Europe/Berlin', '2026-10-25T23:00:00Z').allowed); // 00:00 Oct 26 local
assert.equal(p(g, 'a', 'Bad/Zone', '2026-10-25T23:00:00Z').rule, 'invalid-time-zone');
